// --- UTILS ---
function randomInRange(min, max, decimals) {
    var val = Math.random() * (max - min) + min;
    return parseFloat(val.toFixed(decimals || 2));
}

function randomChoice(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
}

// bounding box
var minLat = Math.min(...reservePerimeter.map(p => p[0]));
var maxLat = Math.max(...reservePerimeter.map(p => p[0]));
var minLng = Math.min(...reservePerimeter.map(p => p[1]));
var maxLng = Math.max(...reservePerimeter.map(p => p[1]));

// point-in-polygon
function isInside(lat, lng, polygon) {
    let inside = false;

    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
        let xi = polygon[i][0], yi = polygon[i][1];
        let xj = polygon[j][0], yj = polygon[j][1];

        let intersect =
            ((yi > lng) !== (yj > lng)) &&
            (lat < (xj - xi) * (lng - yi) / (yj - yi) + xi);

        if (intersect) inside = !inside;
    }

    return inside;
}

// genera punto valido
function generatePoint() {
    let lat, lng;

    do {
        lat = Math.random() * (maxLat - minLat) + minLat;
        lng = Math.random() * (maxLng - minLng) + minLng;
    } while (!isInside(lat, lng, reservePerimeter));

    return {
        lat: parseFloat(lat.toFixed(6)),
        lng: parseFloat(lng.toFixed(6))
    };
}

