// Campi riservati: NON vanno in data
const RESERVED = new Set(['device_id', 'latitude', 'longitude', 'timestamp']);

// Tutto il resto → data (mapping generico, zero opinioni sui nomi)
const data = {};
Object.entries(p).forEach(([k, v]) => {
    if (!RESERVED.has(k)) data[k] = v;
});

const transformed = {
    device_id: deviceId,
    type: 'environmental',
    data,
    attributes: {
        lat: p.latitude  ?? null,
        lng: p.longitude ?? null
    },
    timestamp: p.timestamp ?? new Date().toISOString()
};

// Output 1: messaggio MQTT
const mqttMsg = {
    topic:   `smartpark/telemetry/${deviceId}`,
    payload: JSON.stringify(transformed),
    qos:     0,
    retain:  false
};

// Output 2: HTTP 202 (riusa msg originale che ha req/res)
msg.statusCode = 202;
msg.headers    = { 'Content-Type': 'application/json' };
msg.payload    = JSON.stringify({
    ok:        true,
    device_id: deviceId,
    topic:     `smartpark/telemetry/${deviceId}`,
    fields:    Object.keys(data).length
});

return [mqttMsg, msg];
